type Settings = { monthly_price_cents: number; currency: string; payment_instructions: string; payment_contact_label: string; payment_contact_url: string };
type Profile = { id: string; email: string; display_name: string | null; role: "user" | "admin" };
type Entitlement = { active: boolean; source: string };
type PublicCourse = { id: string; slug: string; title: string; level: string; description: string; learning_outcome: string; requires_subscription: boolean; units_count: number; lessons_count: number; pilot_unit_id: string | null };
type Progress = { current_activity_number: number; completion_percent: number; best_score: number; status: "not_started" | "in_progress" | "completed"; updated_at?: string };
type DashboardCourse = PublicCourse & { available_lessons: number; completed_lessons: number; completion_percent: number; current_lesson: { id: string; title: string; slug: string; estimated_minutes: number; progress: Progress | null } | null };
type DashboardData = { profile: Profile; entitlement: Entitlement; courses: DashboardCourse[]; continue_lesson: DashboardCourse["current_lesson"] | null };
type LessonLite = { id: string; slug: string; lesson_number: number; title: string; description: string; estimated_minutes: number; available: boolean; locked_reason: string | null; activity_count: number };
type CourseDetail = { id: string; slug: string; title: string; level: string; description: string; learning_outcome: string; requires_subscription: boolean; units: Array<{ id: string; unit_number: number; title: string; focus: string; grammar_topic: string; estimated_minutes: number; is_pilot: boolean; lessons: LessonLite[] }> };
type Activity = { id: string; activity_number: number; kind: string; title: string; instructions: string; content: Record<string, any>; estimated_minutes: number; has_audio: boolean };
type PlacementQuestion = { id: string; skill: "grammar" | "vocabulary" | "reading" | "listening" | "writing" | "speaking"; kind: "choice" | "text" | "record" | "listening"; cefr_level?: "A1" | "A2" | "B1" | "B2" | "C1" | "C2"; prompt: string; options?: Array<{ id: string; text: string }>; audio_available?: boolean; audio_text?: string; adaptive_key?: string };
type PlacementResult = { id: string; total_score: number; recommended_level: "Starter" | "A1" | "A2" | "B1" | "B2" | "C1" | "C2"; skill_scores: Record<string, number>; completed_at: string };
type LessonData = { course: { id: string; slug: string; title: string; level: string }; unit: { id: string; unit_number: number; title: string; focus: string; grammar_topic: string; target_words: string[] }; lesson: { id: string; slug: string; title: string; description: string; learning_objective: string; estimated_minutes: number }; unit_audio_activity_id?: string | null; activities: Activity[]; progress: Progress };
type AttemptResult = { result: { score: number; correct: boolean; completed: boolean; feedback: any }; progress: Progress };
type View = "landing" | "dashboard" | "courses" | "course" | "lesson" | "membership" | "placement" | "games" | "admin";
type AuthMode = "login" | "signup" | "reset";

