    <section className="public-course-strip"><div><span className="eyebrow">{l.available}</span><h2>Course → Unit → Lesson</h2><p>{l.preview}</p></div><div className="public-course-list">{courses.map((course) => <article role="button" tabIndex={0} key={course.id} onClick={() => onCourse(course.slug)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") onCourse(course.slug); }}><span>{course.level}</span><div><strong>{course.title}</strong><small>{course.units_count} {l.units}</small></div><ChevronLeft size={17}/></article>)}</div></section>
